// O[M,N] = A[M,K] @ B[N,K]^T   (row-major), fp32 accumulate, bf16 RN out
template<int Tm, int Tn>
double bench(sycl::queue& q, int M, int N, int K, int iters){
  bf16* A = sycl::malloc_device<bf16>(size_t(M)*K, q);
  bf16* B = sycl::malloc_device<bf16>(size_t(N)*K, q);
  bf16* O = sycl::malloc_device<bf16>(size_t(M)*N, q);
  q.parallel_for(sycl::range<1>(size_t(M)*K), [=](sycl::id<1> i){ A[i]=bf16(0.01f); }).wait();
  q.parallel_for(sycl::range<1>(size_t(N)*K), [=](sycl::id<1> i){ B[i]=bf16(0.01f); }).wait();
  auto t0 = std::chrono::steady_clock::now();
  for(int it=0; it<iters; it++){
    q.parallel_for(sycl::range<2>(M/Tm, N/Tn), [=](sycl::id<2> id){
      int r0 = int(id[0])*Tm, c0 = int(id[1])*Tn;
      float acc[Tm][Tn];
      for(int i=0;i<Tm;i++) for(int j=0;j<Tn;j++) acc[i][j]=0.f;
      for(int k=0;k<K;k++){
        float av[Tm];
        for(int i=0;i<Tm;i++) av[i]=(float)A[size_t(r0+i)*K+k];
        float bv[Tn];
        for(int j=0;j<Tn;j++) bv[j]=(float)B[size_t(c0+j)*K+k];
        for(int i=0;i<Tm;i++) for(int j=0;j<Tn;j++) acc[i][j]+=av[i]*bv[j];
      }
      for(int i=0;i<Tm;i++) for(int j=0;j<Tn;j++) O[size_t(r0+i)*N+c0+j]=bf16(acc[i][j]);
    }).wait();
  }
  auto t1 = std::chrono::steady_clock::now();
  double ms = std::chrono::duration<double,std::milli>(t1-t0).count()/iters;
  double gflops = 2.0*M*N*K/ms/1e6;
  // checksum
  float* H = (float*)malloc(size_t(M)*N*sizeof(float));
  bf16* Hb = (bf16*)malloc(size_t(M)*N*sizeof(bf16));
  q.memcpy(Hb, O, size_t(M)*N*sizeof(bf16)).wait();
  double s=0; for(size_t i=0;i<size_t(M)*N;i++) s+=(float)Hb[i];
  printf("Tm=%d Tn=%d M=%d N=%d K=%d: %.1f ms %.1f GFLOPS sum=%f\n",Tm,Tn,M,N,K,ms,gflops,s/(M*N));
  sycl::free(A,q); sycl::free(B,q); sycl::free(O,q); free(H); free(Hb);
  return ms;
}
