    NVTX_RANGE_FN();
    (void)scratch;
    size_t N = size_t(B) * T;
    if (N == 0) return;
    // Pass 1: per-row dnorm_mean, dnorm_norm_mean (sequential, deterministic)
    float* row_a = sycl::malloc_device<float>(N, q); // dnorm_mean
    float* row_b = sycl::malloc_device<float>(N, q); // dnorm_norm_mean
