        size_t other_idx = (b * NH * N * d) + (n * NH * d) + (nh * d) + dd;
        out[other_idx] = inp[idx];
    }).wait();
}

inline void unpermute_backward(floatX* dinp, const floatX* dout,
                               int B, int N, int NH, int d, sycl::queue& q_) {
    size_t total = size_t(B) * NH * N * d;
    if (total == 0) return;
