        q_.memset(out, 0, size_t(max_num_block_sums) * sizeof(float)).wait();
    }
    if (count == 0 || num_slices <= 0) return;
    // one partial sum per slice, deterministic accumulation order inside kernel
    const T* v = values; float* o = out;
    q_.parallel_for(sycl::range<1>(size_t(num_slices)), [=](sycl::id<1> id) {
        size_t s = id[0];
        const T* d = v + s * (size_t)stride;
        float acc = 0.f;
        for (size_t i = 0; i < count; i++) {
            float x = (float)d[i];
            acc += x * x;
        }
        o[s] = o[s] + acc;
    }).wait();
}

#endif

/*
Global norm, used in gradient clipping (ported from llmc/global_norm.cuh).
Deterministic: per-element squares accumulated in fixed order.
*/
#ifndef SYCL_GLOBAL_NORM_HPP
#define SYCL_GLOBAL_NORM_HPP

#include <assert.h>
#include <stddef.h>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.hpp"

// ----------------------------------------------------------------------------

// Helper function determines the maximum number of block sums (kept for API compat)
inline int get_max_num_block_sums(int* num_slices_all, int numel) {
    int mx = 0;
    for (int i = 0; i < numel; i++) { mx = std::max(mx, num_slices_all[i]); }
    return std::max(mx, 1);
}

template<typename T>
inline void global_norm_squared(float* out, const T* values, size_t count, ptrdiff_t stride, int num_slices, int max_num_block_sums, bool reset, sycl::queue& q_) {
    if (reset) {
        q_.memset(out, 0, size_t(max_num_block_sums) * sizeof(float)).wait();
    }
    if (count == 0 || num_slices <= 0) return;
    // one partial sum per slice, deterministic accumulation order inside kernel
    const T* v = values; float* o = out;
    q_.parallel_for(sycl::range<1>(size_t(num_slices)), [=](sycl::id<1> id) {
        size_t s = id[0];
        const T* d = v + s * (size_t)stride;
        float acc = 0.f;
        for (size_t i = 0; i < count; i++) {
            float x = (float)d[i];
            acc += x * x;
        }
        o[s] = o[s] + acc;
    }).wait();
}

#endif

/*
Single-device "multi-GPU" support (ported from llmc/zero.cuh).
No NCCL/MPI: single process path only. Keeps the same API shape so that
train_gpt2.cpp reads like the CUDA version.
*/

#ifndef LLMC_ZERO_HPP
#define LLMC_ZERO_HPP

#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <stddef.h>

// defines: fcloseCheck, fwriteCheck
#include "utils.h"

// ----------------------------------------------------------------------------
// Parameters specific to training on multiple GPUs (single-device here).
typedef struct {
    int process_rank;      // 0
    int num_processes;     // 1
    int local_device_idx;  // 0

    int zero_stage;        // 0 or 1 (sharding bookkeeping only, single shard)
    size_t shard_num_parameters;
} MultiGpuConfig;

// one global variable to hold the multi-GPU configuration for this process
inline MultiGpuConfig multi_gpu_config;

inline MultiGpuConfig multi_gpu_config_init(int num_processes, int process_rank, int gpus_per_node,
                                            const char* server_ip, const char* fs_path, const char* nccl_init_method) {
    (void)num_processes; (void)process_rank; (void)gpus_per_node;
    (void)server_ip; (void)fs_path; (void)nccl_init_method;
    printf("Multi-GPU support is disabled. Using a single device.\n");
    MultiGpuConfig result;
    result.process_rank = 0;
    result.num_processes = 1;
    result.local_device_idx = 0;
    result.zero_stage = 0;
    result.shard_num_parameters = 0;
    return result;
}

inline void multi_gpu_config_free(MultiGpuConfig* config) {
    (void)config;
}

inline void multi_gpu_barrier(const MultiGpuConfig* config) {
    (void)config;
}

// Offset and size of a tensor shard
typedef struct {
    ptrdiff_t offset;
    size_t size;
} ShardInfo;

// Get info about sharding for a tensor of elements many numbers
inline ShardInfo multi_gpu_get_shard_offset(size_t elements, const MultiGpuConfig* config, int shard_at_stage) {
    const int nproc = config->num_processes;
    if (config->zero_stage >= shard_at_stage) {
        if (elements % (size_t)nproc != 0) {
            fprintf(stderr, "Number of elements %zu must be a multiple of the number of processes %d\n", elements, nproc);
            exit(EXIT_FAILURE);
        }
        return {(ptrdiff_t)(config->process_rank * (elements / (size_t)nproc)), elements / (size_t)nproc};
    } else {
        return {0, elements};
    }
}

// No-op on a single device.
template<int N>
inline void multi_gpu_async_reduce_gradient(
        floatX* const (&pointers)[N], const size_t (&pointers_sizes)[N],
        MultiGpuConfig* config, sycl::queue& q) {
    (void)pointers; (void)pointers_sizes; (void)config; (void)q;
    return;
}

// convenience macro that only prints if the rank of process is zero
#define printf0(...) if (::multi_gpu_config.process_rank == 0) { printf(__VA_ARGS__); }

inline void set_zero_configs(MultiGpuConfig* config, int zero_stage, size_t total_parameters) {
    config->zero_stage = 0;
    config->shard_num_parameters = total_parameters;
    // Check the Zero Stage and define sharding parameters
    if (zero_stage == 0) {
        printf0("| Zero Optimization is disabled                                              |\n");
    }
    else if (zero_stage == 1) {
        if (total_parameters % (size_t)config->num_processes != 0) {
            printf0("| Zero Optimization is disabled, Can't equally partition parameters          |\n");
            config->zero_stage = 0;
        }
        else {
            config->zero_stage = 1;
            config->shard_num_parameters = total_parameters / (size_t)config->num_processes;
        }
    }
    else {
        printf0("| Disabling Zero Optimization, Zero Stage2 and Stage3 are not yet supported  |\n");
        config->zero_stage = 0;
    }
}

// Compute sum of a single CPU value across all GPU processes. No-op when multi-GPU is disabled.
inline float multi_gpu_cpu_float_sum(float value, MultiGpuConfig* config) {
    (void)config;
    return value;
}

#endif

