        size_t inp_idx = ((b * (size_t)N + n) * 3 * (size_t)NH * d) + (nh * (size_t)d) + dd;
        dinp[inp_idx] = dq[idx];
        dinp[inp_idx + NH * d] = dk[idx];
        dinp[inp_idx + 2 * NH * d] = dv[idx];
